// === Tab: Flower.js ===
class Flower{
	constructor(start,head,r,option = {}){
		this.start = start
		this.head = head
		this.bend = p5.Vector.random3D()
		this.bend.z = abs(this.bend.z)
		this.pedalCount = option.padelCount || floor(randomGaussian(30,5))
		this.startAngle = random(PI*2)
		this.r = r
		this.t = floor(random(60))
		this.half =  option.half || random([true,false])
	}

	setHeading(vec){
		this.head = vec.copy()
		this.head.normalize()
		// print(1)
	}

	draw(){
		push()
		translate(this.start)

		// push()
		// strokeWeight(0.2)
		// stroke("rgb(245,0,255)")
		// line(0,0,0,this.head.x*50,this.head.y*50,this.head.z*50)
		// stroke("rgb(0,185,255)")
		// line(0,0,0,0,0,100)
		// stroke("rgb(255,0,0)")
		// line(0,0,0,100,0,0)
		// stroke("rgb(0,255,16)")
		// line(0,0,0,0,100,0)
		// pop()

		// rotateX(asin())
		// rotateX(atan(this.head.y/this.head.z))
		rotateX(createVector(this.head.y,this.head.z).heading()-PI/2)
		rotateY(asin(this.head.x/this.head.mag()))

		// push()
		// stroke("rgb(0,185,255)")
		// line(0,0,0,0,0,100)
		// stroke("rgb(255,0,0)")
		// line(0,0,0,100,0,0)
		// stroke("rgb(0,255,16)")
		// line(0,0,0,0,100,0)
		// pop()

		const pedalModifier = this.half?0.5:1
		for(let i=0;i<this.pedalCount * pedalModifier;i++){
			const ang = map(i,0,this.pedalCount,this.startAngle,this.startAngle+2*PI)

			const wavDelta = map(i,0,this.pedalCount,0,PI*2)
			const waving1 = sin(this.t*0.05+wavDelta) * this.r*0.1
			const waving2 = sin(this.t*0.03+wavDelta) * this.r*0.1
			// const waving2 = sin(this.t*0.05) * 10

			bezier(
				cos(ang)*0, sin(ang)*0, 0,
				cos(ang)*0, sin(ang)*0, this.r,
				cos(ang)* this.r*0.5, sin(ang)* this.r, this.r*1.5+waving1,
				cos(ang)* this.r*1.5 + this.bend.x*this.r*0.5, sin(ang)* this.r*1.5 + this.bend.y*this.r*0.5, this.r + this.bend.z*this.r*0.5+waving2,
			)
		}

		pop()

		this.t++
	}

}

// === Tab: Branch.js ===
class Branch{
	constructor(start,v1,v2,v3,parent){
		this.start = start
		this.vectorArr = [
			v1,
			v2,
			v3
		]
		this.end = this.start.copy().add(this.vectorArr[0]).add(this.vectorArr[1]).add(this.vectorArr[2])
		this.parent = parent || null
		this.updateBezierCoor()
	}

	updateBezierCoor(){
		this.bezierCoor = [
			this.start.x, this.start.y, this.start.z,
			this.start.x+this.vectorArr[0].x, this.start.y+this.vectorArr[0].y, this.start.z+this.vectorArr[0].z,
			this.start.x+this.vectorArr[0].x+this.vectorArr[1].x, this.start.y+this.vectorArr[0].y+this.vectorArr[1].y, this.start.z+this.vectorArr[0].z+this.vectorArr[1].z,
			this.start.x+this.vectorArr[0].x+this.vectorArr[1].x+this.vectorArr[2].x, this.start.y+this.vectorArr[0].y+this.vectorArr[1].y+this.vectorArr[2].y, this.start.z+this.vectorArr[0].z+this.vectorArr[1].z+this.vectorArr[2].z
		]
	}

	draw(){
		// this.vectorArr[2].mult(0.99)
		// this.updateBezierCoor()
		bezier(...this.bezierCoor)
	}
}

