let branchArr = []
let flowerArr = []
let mainHue
let cameraRotationSpeed

function init(){
	branchArr = []
	flowerArr = []
	allHalf = random([true,null])
	generateBranches(createVector(0,0,0),createVector(0,0,50))
	mainHue = random(360)
	frameCount = 0
	cameraRotationSpeed = random([-1,1])
}

function mousePressed(){
	init()
}

function keyPressed(){
	if(key=="s" || key=="S"){
		save()
	}
	if(key=="r" || key=="R"){
		init()
	}
}

function setup() {
	cnv=createCanvas(max(windowWidth, windowHeight), max(windowWidth, windowHeight), WEBGL);
	init()
}

function draw() {
	push()

	camera(cos(frameCount*0.003*cameraRotationSpeed)*1000,sin(frameCount*0.003*cameraRotationSpeed)*1000,0,0,0,height*0.3,0,0,-1)
	// camera(cos(frameCount*0.05)*800,sin(frameCount*0.05)*800,800,0,-200,0)
	// perspective(1)
	// translate(0,height/3)

	background(255);
	noFill()
	colorMode(HSB)
	stroke(mainHue,80,40,0.3)
	strokeWeight(1)
	// strokeCap(SQUARE)
	for(let branch of branchArr){
		// stroke(branch.color)
		branch.draw()
	}

	for(let flower of flowerArr){
		// stroke(flower.color)
		flower.draw()
	}
	pop()

	camera(0,0,-101600,0,0,0)
	translate(-width/2,-height/2,-100800)

	fill(0)
	const padding = width/15

	rect(0,0,width,padding)
	rect(width-padding,0,padding,height)
	rect(0,height-padding,width,padding)
	rect(0,0,padding,height)

}

function generateBranches(start,lastVec){
	const v1 = lastVec.copy().setMag(randomGaussian(width/20,width/25))
	const v2 = p5.Vector.random3D().setMag(randomGaussian(width/20,width/25))
	v2.z = abs(v2.z)
	const v3 = p5.Vector.random3D().setMag(randomGaussian(width/20,width/25))
	v3.z = abs(v3.z)
	const newBranch = new Branch(start,v1,v2,v3)
	newBranch.color = random(100,255)
	branchArr.push(newBranch)
	// const end = start.copy().add(v1).add(v2).add(v3)
	// push()
	// strokeWeight(15)
	// stroke(255)
	// point(end.x,end.y,end.z)
	// print(end)
	// pop()
	if(newBranch.end.z<height*0.4 && random()<0.5 && sqrt(pow(newBranch.end.x,2)+pow(newBranch.end.y,2))<width*0.2 || branchArr.length<4){
		generateBranches(newBranch.end,v3)
		generateBranches(newBranch.end,v3)
		if(random()<0.3){
			generateSmallBranches(newBranch.end,v3)
		}
	}else{
		const newFlower = new Flower(newBranch.end,v3,v3.mag(),{half:allHalf})
		newFlower.setHeading(v3)
		flowerArr.push(newFlower)
	}
}

function generateSmallBranches(start,lastVec){
	const v1 = lastVec.copy().setMag(randomGaussian(width/20,width/60))
	const v2 = p5.Vector.random3D().setMag(randomGaussian(width/20,width/60))
	v2.z = abs(v2.z)
	const v3 = p5.Vector.random3D().setMag(randomGaussian(width/40,width/60))
	v3.z = abs(v3.z)
	const newBranch = new Branch(start,v1,v2,v3)
	newBranch.color = random(100,255)
	branchArr.push(newBranch)
	if(newBranch.end.z<height*0.4 && random()<0.4 && sqrt(pow(newBranch.end.x,2)+pow(newBranch.end.y,2))<width*0.2 || branchArr.length<4){
		for(let i=0;i<random(1,4);i++){
			generateSmallBranches(newBranch.end,v3)
		}
	}else{
		const newFlower = new Flower(newBranch.end,v3,v3.mag(),{half:true,padelCount:50})
		newFlower.setHeading(v3)
		flowerArr.push(newFlower)
	}
}

// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

